<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue'
import {usePhasePage} from '../phasePage'
import {useDocumentExpiryText,type ExpiryPage,type ExpiryItem} from '../documentExpiry'
import DocumentMaintenanceDialog from './DocumentMaintenanceDialog.vue'
import PhaseStatus from './PhaseStatus.vue'
const props=defineProps<{employeeId:string;employeeName:string;status:'due'|'expired'}>(),emit=defineEmits<{close:[];changed:[]}>(),{api,home,t,p,load,loading,failure}=usePhasePage(),{x}=useDocumentExpiryText()
const dialog=ref<HTMLDialogElement|null>(null),offset=ref(0),data=ref<ExpiryPage|null>(null),selected=ref<ExpiryItem|null>(null)
function close(){if(!selected.value)emit('close')}
function refresh(){if(!home.value?.employeeManage)return;data.value=null;const query=new URLSearchParams({employeeId:props.employeeId,days:'30',status:props.status,limit:'50',offset:String(offset.value)});void load(()=>api().get<ExpiryPage>('/document-expiries?'+query),result=>{if(offset.value>0&&offset.value>=result.total){offset.value=Math.max(0,Math.floor((result.total-1)/50)*50);refresh();return}data.value=result})}
function changed(){refresh();emit('changed')}
function page(delta:number){offset.value=Math.max(0,offset.value+delta);refresh()}
onMounted(()=>{dialog.value?.showModal?.();refresh()});onBeforeUnmount(()=>dialog.value?.close?.())
</script>
<template><dialog ref="dialog" class="wf-schedule-dialog wf-bulk-dialog" aria-modal="true" aria-labelledby="wf-employee-expiry-title" @cancel.prevent="close"><header class="wf-toolbar"><h2 id="wf-employee-expiry-title">{{employeeName}} · {{x(status)}}</h2><button type="button" class="wf-dialog-close" :aria-label="x('close')" :disabled="!!selected" @click="close">×</button></header><p class="wf-hint">{{status==='due'?x('badgeHint'):x('expiredHint')}}</p><PhaseStatus :loading="loading" :failure="failure"/><p v-if="!home?.employeeManage" role="alert">{{p('noAccess')}}</p><template v-if="data&&!failure"><p class="wf-hint">{{data.today}} · {{data.timezone}} · {{data.total}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{x('type')}}</th><th>{{x('expiry')}}</th><th>{{t('status')}}</th><th>{{t('manage')}}</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.documentId"><td>{{row.typeName}}</td><td>{{row.expiresOn}}</td><td>{{row.daysRemaining===0?x('today'):x(row.status)}} · {{Math.abs(row.daysRemaining)}} {{x('dayUnit')}}</td><td><button type="button" :disabled="!!selected" :aria-label="x('maintain')+' · '+row.typeName+' · '+row.expiresOn" @click="selected=row">{{x('maintain')}}</button></td></tr><tr v-if="!data.items.length"><td colspan="4" class="wf-empty">{{x('empty')}}</td></tr></tbody></table></div><footer class="wf-pagination"><span>{{data.total?offset+1:0}}–{{Math.min(offset+50,data.total)}} / {{data.total}}</span><button type="button" :disabled="loading||!!selected||offset===0" @click="page(-50)">{{t('previous')}}</button><button type="button" :disabled="loading||!!selected||offset+50>=data.total" @click="page(50)">{{t('next')}}</button></footer></template><footer class="wf-form-actions"><button v-if="failure" type="button" :disabled="loading||!!selected" @click="refresh">{{p('reload')}}</button><button type="button" :disabled="!!selected" @click="close">{{x('close')}}</button></footer><DocumentMaintenanceDialog v-if="selected" :employee-id="employeeId" :employee-name="employeeName" :document-id="selected.documentId" @close="selected=null" @changed="changed"/></dialog></template>
